export function normalizeLanguage(value){
  const code=typeof value==='string'?value.trim().toLowerCase().split(/[-_]/)[0]:'';
  return SUPPORTED_LANGUAGES.includes(code)?code:'en';
}
function defaultStorage(){try{return globalThis.localStorage;}catch{return undefined;}}
function defaultDocument(){try{return globalThis.document;}catch{return undefined;}}
export function translate(key,language='en',values={}){
  const lang=normalizeLanguage(language),template=messages[lang][key]??messages.en[key]??key;
  return template.replace(/\{([a-zA-Z0-9_]+)\}/g,(_,name)=>String(values[name]??''));
}
export function readLanguage(storage){
  try{return normalizeLanguage((storage===undefined?defaultStorage():storage)?.getItem(LANGUAGE_STORAGE_KEY));}catch{return'en';}
}
export function writeLanguage(language,storage){
  const normalized=normalizeLanguage(language);
  try{(storage===undefined?defaultStorage():storage)?.setItem(LANGUAGE_STORAGE_KEY,normalized);}catch{}
  return normalized;
}
export function setLanguagePresentation(language,{storage,document,render=()=>{}}={}){
  const selected=writeLanguage(language,storage);
  const target=document===undefined?defaultDocument():document;
  if(target)applyStaticTranslations(target,selected);
  render(selected);
  return selected;
}
export function applyStaticTranslations(document,language){
  const lang=normalizeLanguage(language);document.documentElement.lang=lang;document.title=translate('document.title',lang);
  for(const node of document.querySelectorAll('[data-i18n]'))node.textContent=translate(node.dataset.i18n,lang);
  for(const node of document.querySelectorAll('[data-i18n-aria-label]'))node.setAttribute('aria-label',translate(node.dataset.i18nAriaLabel,lang));
  for(const node of document.querySelectorAll('[data-i18n-title]'))node.setAttribute('title',translate(node.dataset.i18nTitle,lang));
}
export function formatDateLabel(date,language='en'){
  const locale={en:'en-GB',de:'de-DE',tr:'tr-TR'}[normalizeLanguage(language)];
  return new Intl.DateTimeFormat(locale,{dateStyle:'medium',timeZone:'UTC'}).format(new Date(`${date}T12:00:00Z`));
}

export function localizedProfileLabel(profile,language){
  const lang=normalizeLanguage(language),key=`profile.${profile.id}`;
  if(messages[lang][key])return translate(key,lang);
  if(profile.composition){
    const pairs={'18-17':['18°','17°'],'19p5-17p5':['19.5°','17.5°'],'15-15':['15°','15°'],'13-13':['13°','13°']};
    const [fajr,isha]=pairs[profile.composition.twilightPair]??['Fajr','Isha'];
    const night=profile.composition.highLatitudeMode==='physical'?translate('summary.noEstimate',lang):translate('summary.nightEstimate',lang);
    return translate('profile.local-composed',lang,{fajr,isha,factor:profile.composition.asrShadowFactor,night});
  }
  return profile.label;
}
export function localizedProfileScope(profile,language,context={}){
  const lang=normalizeLanguage(language),id=profile.id;
  if(profile.family)return localizedFamilyScope(profile.family,lang,context.calculation?.intervalPolicy?.mode??(profile.id?.endsWith('-reference45-v1')?'reference45':profile.highLatitudeMode));
  if(id.endsWith('-observer-v1'))return translate('scope.observer',lang,{base:translate('scope.composed',lang)});
  const key=id.startsWith('diyanet-published-')?'scope.diyanet':id==='local-northern-seasonal-v1'?'scope.seasonal'
    :id.startsWith('egypt-')?'scope.egypt':id.startsWith('fcna-usa')?'scope.fcna-us'
    :id.startsWith('fcna-canada')?'scope.fcna-ca':id.startsWith('kemenag-')?'scope.kemenag':profile.composition?'scope.composed':'scope.fallback';
  return translate(key,lang,{description:profile.sourceScope});
}
export function localizedSourceLabel(key,language){
  const normalized=key.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
  const result=translate(`source.${normalized}`,language);
  return result===`source.${normalized}`?key:result;
}
export function localizedEventName(event,language){return translate(`event.${event}`,language);}
export function resolveMethodProfile(method,{asrFactor,nightMode,ramadanMode}={}){
  if(!method||typeof method.id!=='string'||typeof method.defaultProfile!=='string')throw new TypeError('A method catalogue entry is required');
  if(method.id==='diyanet'||method.id==='kemenag')return method.defaultProfile;
  const factors=method.asrFactors??[],nights=method.nightModes??[],ramadans=method.ramadanModes??[];
  const fallbackFactor=Number(method.defaultProfile.match(/shadow([12])/i)?.[1]??factors[0]??1);
  const factor=factors.includes(Number(asrFactor))?Number(asrFactor):fallbackFactor;
  const availableModes=ramadans.length?ramadans:nights;
  const requestedMode=ramadans.length?ramadanMode:nightMode;
  const fallbackMode=method.defaultProfile.match(/-(physical|angle-night|reference45|calendar|ramadan|ordinary)-v1$/)?.[1]??availableModes[0];
  const mode=availableModes.includes(requestedMode)?requestedMode:fallbackMode;
  if(!mode)return method.defaultProfile;
  const candidate=`sunni-${method.id}-shadow${factor}-${mode}-v1`;
  return method.profiles?.includes(candidate)?candidate:method.defaultProfile;
}
export function localizedFamilyName(id,language){
  const key=`family.${id}`;const value=translate(key,language);return value===key?id:value;
}
export function localizedFamilyScope(id,language,mode){
  const key=`family.scope.${id}`;let value=translate(key,language);
  if(value===key)value=translate('family.scope.other',language);
  if(id==='umm-al-qura')value+=` ${translate('ramadan.note',language)}`;
  if(mode==='reference45')value+=` ${translate('night.reference45Scope',language)}`;
  return value;
}
export function localizedStatus(status,role,language){
  if(role&&role!=='prayer-start-model')return translate('status.marker',language);
  const value=translate(`status.${status}`,language);
  return value===`status.${status}`?translate('status.unavailable',language):value;
}
export function localizedReason(reason,language){
  if(!reason)return'';
  if(reason==='missing-seasonal-crossing-estimated-from-reference45-night-fraction')return translate('reason.referenceEstimated',language);
  if(reason.startsWith('reference45-'))return translate(/scope|latitude|outside-supported/.test(reason)?'reason.referenceScope':/night|horizon/.test(reason)?'reason.referenceNight':'reason.referenceFailure',language);
  if(/policy|seasonal|northern/i.test(reason))return translate('reason.policy',language);
  if(/crossing|solar-cycle|transit|horizon|sun-|twilight|shadow/i.test(reason))return translate('reason.noCrossing',language);
  return translate('reason.unknown',language,{reason});
}
export function localizedError(detail,language){
  const normalized=normalizeLanguage(language),exact=translate(`error.detail.${detail}`,normalized);
  if(exact!==`error.detail.${detail}`)return exact;
  if(/malaysia|malaysian/i.test(detail))return translate('error.malaysiaDomain',normalized);
  if(/outside.*(domain|supported)/i.test(detail))return translate('error.domain',normalized);
  if(/transit.*(civil date|local date)|multiple apparent solar transit/i.test(detail))return translate('error.transit',normalized);
  if(/time.?zone|IANA/i.test(detail))return translate('error.timezone',normalized);
  if(/latitude/i.test(detail))return translate('error.latitude',normalized);
  if(/longitude/i.test(detail))return translate('error.longitude',normalized);
  if(/date|year/i.test(detail))return translate('error.date',normalized);
  return translate('error.other',normalized,{detail});
}
export function localizedRuleDescription(day,event,language){
  const lang=normalizeLanguage(language),profile=day.profile,rule=day.events[event],meta=day.astronomy?.model??{};
  if(event==='isha'&&day.calculation?.intervalPolicy)return translate('rule.ishaInterval',lang,{minutes:day.calculation.intervalPolicy.minutes});
  if(rule.status==='estimated'&&profile.id.endsWith('-reference45-v1'))return translate('rule.reference45',lang);
  if(rule.status==='estimated')return translate('rule.estimated',lang);
  if(profile.northernPolicyThresholdDegrees!==null&&(event==='fajr'||event==='isha')&&day.calculation.northernPolicy){
    const policy=day.calculation.seasonalPolicy;
    return translate(policy?.status==='available'&&policy.day?.[event]?.mode!=='ordinary'?'rule.summer':'rule.northern',lang);
  }
  if(profile.id==='kemenag-worked-example-point-v1'&&(event==='fajr'||event==='isha'))return translate('rule.kemenagAngle',lang,{angle:event==='fajr'?(meta.fajrAngleDegrees??20):(meta.ishaAngleDegrees??18),margin:rule.adjustmentMinutes??0});
  if(profile.id==='kemenag-worked-example-point-v1'&&event==='sunrise')return translate('rule.kemenagHorizon',lang,{angle:meta.horizonDepressionDegrees??1,margin:rule.adjustmentMinutes??0});
  if(profile.id==='kemenag-worked-example-point-v1'&&event==='dhuhr')return translate('rule.kemenagDhuhr',lang,{margin:rule.adjustmentMinutes??0});
  if(profile.id==='kemenag-worked-example-point-v1'&&event==='asr')return translate('rule.kemenagAsr',lang,{factor:meta.asrShadowFactor??1,margin:rule.adjustmentMinutes??0});
  if(profile.id==='kemenag-worked-example-point-v1'&&event==='maghrib')return translate('rule.kemenagMaghrib',lang,{angle:meta.horizonDepressionDegrees??1,margin:rule.adjustmentMinutes??0});
  if(profile.id==='sunni-jakim-shadow1-physical-v1'){
    const angle=event==='fajr'?(meta.fajrAngleDegrees??18):(meta.ishaAngleDegrees??18);
    if(event==='fajr'||event==='isha')return translate(`rule.jakim.${event}`,lang,{angle});
    if(event==='sunrise')return translate('rule.jakim.sunrise',lang);
    if(event==='dhuhr')return translate('rule.jakim.dhuhr',lang,{seconds:Math.round((rule.adjustmentMinutes??0)*60)});
    if(event==='asr')return translate('rule.jakim.asr',lang,{factor:meta.asrShadowFactor??1});
    if(event==='maghrib')return translate('rule.jakim.maghrib',lang);
  }
  if(event==='sunrise')return translate('rule.sunrise',lang,{margin:rule.adjustmentMinutes??0});
  if(event==='dhuhr')return translate(rule.role==='solar-noon-marker'?'rule.noonMarker':'rule.dhuhr',lang,{margin:rule.adjustmentMinutes??0});
  if(event==='asr')return translate('rule.asr',lang,{factor:meta.asrShadowFactor??profile.composition?.asrShadowFactor??1,margin:rule.adjustmentMinutes??0});
  if(event==='maghrib')return translate(rule.role==='sunset-marker'?'rule.sunsetMarker':'rule.maghrib',lang,{margin:rule.adjustmentMinutes??0});
  if(event==='fajr'||event==='isha'){
    const angle=event==='fajr'?(meta.fajrAngleDegrees??18):(profile.northernPolicyThresholdDegrees!==null&&day.calculation.northernPolicy?16:(meta.ishaAngleDegrees??17));
    return translate(`rule.${event}`,lang,{angle,margin:rule.adjustmentMinutes??0});
  }
  return translate('rule.missing',lang);
}
